@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar d-flex gap-3 mb-3 p-2 bg-light rounded">
        <span><strong>Total:</strong> @_allTasks.Count</span>
        <span><strong>To Do:</strong> @GetColumnTasks("To Do").Count</span>
        <span><strong>In Progress:</strong> @GetColumnTasks("In Progress").Count</span>
        <span><strong>Done:</strong> @GetColumnTasks("Done").Count</span>
        <span class="text-danger"><strong>Overdue:</strong> @_allTasks.Count(t => t.DueDate < DateTime.Today)</span>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="_searchTerm" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="d-flex gap-3">
        @foreach (var column in _columns)
        {
            var tasks = GetFilteredColumnTasks(column);
            var colIndex = Array.IndexOf(_columns, column);

            <div class="kanban-column flex-fill border rounded p-2" style="min-width: 250px;">
                <h4>@column <span class="badge bg-secondary">@tasks.Count</span></h4>

                @foreach (var task in tasks)
                {
                    <div class="card mb-2">
                        <div class="card-body p-2">
                            <h6 class="card-title mb-1">@task.Title</h6>
                            <p class="card-text mb-1 small text-muted">@task.Assignee</p>
                            <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                            <span class="small ms-2">@task.DueDate.ToString("MMM dd")</span>
                            <div class="mt-1">
                                @if (colIndex > 0)
                                {
                                    <button class="btn btn-sm btn-outline-secondary me-1"
                                            @onclick="() => MoveTask(task, _columns[colIndex - 1])">Move Left</button>
                                }
                                @if (colIndex < _columns.Length - 1)
                                {
                                    <button class="btn btn-sm btn-outline-secondary"
                                            @onclick="() => MoveTask(task, _columns[colIndex + 1])">Move Right</button>
                                }
                            </div>
                        </div>
                    </div>
                }

                @if (_showForm[column])
                {
                    <div class="border rounded p-2 mt-2">
                        <input type="text" class="form-control form-control-sm mb-1" placeholder="Title"
                               @bind="_formData[column].Title" />
                        <input type="text" class="form-control form-control-sm mb-1" placeholder="Assignee"
                               @bind="_formData[column].Assignee" />
                        <select class="form-select form-select-sm mb-1" @bind="_formData[column].Priority">
                            <option value="High">High</option>
                            <option value="Medium">Medium</option>
                            <option value="Low">Low</option>
                        </select>
                        <input type="date" class="form-control form-control-sm mb-1"
                               @bind="_formData[column].DueDate" />
                        <div class="d-flex gap-1">
                            <button class="btn btn-sm btn-primary" @onclick="() => SaveTask(column)">Save</button>
                            <button class="btn btn-sm btn-secondary" @onclick="() => CancelForm(column)">Cancel</button>
                        </div>
                    </div>
                }
                else
                {
                    <button class="btn btn-sm btn-outline-primary mt-2" @onclick="() => ShowAddForm(column)">Add Task</button>
                }
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = { "To Do", "In Progress", "Done" };
    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchTerm = string.Empty;
    private Dictionary<string, bool> _showForm = new();
    private Dictionary<string, TaskFormModel> _formData = new();

    protected override async Task OnInitializedAsync()
    {
        foreach (var col in _columns)
        {
            _showForm[col] = false;
            _formData[col] = new TaskFormModel();
        }

        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status) =>
        _allTasks
            .Where(t => t.Status == status &&
                        (string.IsNullOrEmpty(_searchTerm) ||
                         t.Title.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase)))
            .ToList();

    private string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = _allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                _allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
    }

    private void ShowAddForm(string column)
    {
        _formData[column] = new TaskFormModel { Priority = "Medium", DueDate = DateTime.Today };
        _showForm[column] = true;
    }

    private void CancelForm(string column)
    {
        _showForm[column] = false;
    }

    private async Task SaveTask(string column)
    {
        var form = _formData[column];
        try
        {
            var newTask = await TaskService.CreateTaskAsync(form.Title, form.Assignee, form.Priority, form.DueDate);
            _allTasks.Add(newTask with { Status = column });
            _showForm[column] = false;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
    }

    private class TaskFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Assignee { get; set; } = string.Empty;
        public string Priority { get; set; } = "Medium";
        public DateTime DueDate { get; set; } = DateTime.Today;
    }
}

