    {
        var form = _formData[column];
        try
        {
            var newTask = await TaskService.CreateTaskAsync(form.Title, form.Assignee, form.Priority, form.DueDate);
            _allTasks.Add(newTask with { Status = column });
            _showForm[column] = false;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
    }

    private class TaskFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Assignee { get; set; } = string.Empty;
        public string Priority { get; set; } = "Medium";
        public DateTime DueDate { get; set; } = DateTime.Today;
    }
}

